def function(inputs, parameters, context):
    df = inputs['cleaned']
    if parameters['species'] is not None:
        df = df[df['species'] == parameters['species']]
    return {'filtered': df}

def function(inputs, parameters, context):
    df = inputs['filtered']
    records_used = df.shape[0]
    mean_body_mass = df['body_mass_g'].mean()
    return {'records_used': records_used, 'mean_body_mass': mean_body_mass}

def function(inputs, parameters, context):
    df = inputs['filtered']
    counts = df['species'].value_counts().reset_index()
    counts.columns = ['species', 'count']
    return {'species_counts': counts}

def function(inputs, parameters, context):
    df = inputs['filtered']
    counts = df['species'].value_counts(normalize=True).reset_index()
    counts.columns = ['species', 'share']
    return {'species_share': counts}

def function(inputs, parameters, context):
    df = inputs['filtered']
    return {'scatter_data': df[['flipper_length_mm', 'body_mass_g']]}

def function(inputs, parameters, context):
    df = inputs['filtered']
    summary = df.groupby('species').agg(count=('species', 'size'), mean_body_mass_g=('body_mass_g', 'mean'), mean_flipper_length_mm=('flipper_length_mm', 'mean')).reset_index()
    return {'species_summary': summary}

def function(inputs, parameters, context):
    df = inputs['filtered']
    if df.shape[0] < 2 or df['flipper_length_mm'].nunique() <= 1 or df['body_mass_g'].nunique() <= 1:
        return {'reading_scatter_output': 'Correlation is unavailable due to insufficient data or constant values.'}
    correlation = df['flipper_length_mm'].corr(df['body_mass_g'])
    records_count = df.shape[0]
    return {'reading_scatter_output': f'Observation count: {records_count}, Correlation: {correlation:.3f}. Note: Association does not establish cause.'}
